@app.get("/accounts/{account_id}", response_model=AccountResponse)
async def get_account(account_id: str, db: Session = Depends(get_db)):
    account = db.query(Account).filter(Account.id == account_id).first()
    if not account:
        raise HTTPException(status_code=404, detail="Account not found")
    return account


@app.get("/accounts")
async def list_accounts(
    owner_id: str = None,
    owner_type: str = None,
    db: Session = Depends(get_db),
):
    query = db.query(Account)
    if owner_id:
        query = query.filter(Account.owner_id == owner_id)
    if owner_type:
        query = query.filter(Account.owner_type == owner_type)

    accounts = query.order_by(Account.created_at.desc()).all()

    return {
        "total": len(accounts),
        "accounts": [
            {
                "id": a.id,
                "owner_id": a.owner_id,
                "owner_type": a.owner_type,
                "account_type": a.account_type,
                "currency": a.currency,
                "balance": float(a.balance),
                "available_balance": float(a.available_balance),
                "pending_balance": float(a.pending_balance),
                "description": a.description,
            }
            for a in accounts
        ],
    }


