@app.get("/entries/payment/{payment_id}")
async def get_payment_entries(payment_id: str, db: Session = Depends(get_db)):
    entries = (
        db.query(LedgerEntry)
        .filter(LedgerEntry.payment_id == payment_id)
        .order_by(LedgerEntry.created_at.asc())
        .all()
    )

    transactions = (
        db.query(LedgerTransaction)
        .filter(LedgerTransaction.payment_id == payment_id)
        .order_by(LedgerTransaction.created_at.asc())
        .all()
    )

    return {
        "payment_id": payment_id,
        "total_entries": len(entries),
        "transactions": [
            {
                "id": t.id,
                "event_type": t.event_type,
                "amount": float(t.amount),
                "currency": t.currency,
                "status": t.status,
                "description": t.description,
                "metadata": t.extra_metadata,   # ✅ FIX 2: was t.metadata
                "created_at": t.created_at.isoformat(),
            }
            for t in transactions
        ],
        "entries": [
            {
                "id": e.id,
                "account_id": e.account_id,
                "entry_type": e.entry_type,
                "event_type": e.event_type,
                "amount": float(e.amount),
                "currency": e.currency,
                "balance_after": float(e.balance_after),
                "description": e.description,
                "created_at": e.created_at.isoformat(),
            }
            for e in entries
        ],
    }


@app.get("/entries/merchant/{merchant_id}")
async def get_merchant_entries(
    merchant_id: str,
    limit: int = Query(default=20, le=100),
    offset: int = 0,
    db: Session = Depends(get_db),
):
    total = db.query(LedgerEntry).filter(
        LedgerEntry.merchant_id == merchant_id
    ).count()

    entries = (
        db.query(LedgerEntry)
        .filter(LedgerEntry.merchant_id == merchant_id)
        .order_by(LedgerEntry.created_at.desc())
        .offset(offset)
        .limit(limit)
        .all()
    )

    return {
        "merchant_id": merchant_id,
        "total": total,
        "has_more": (offset + limit) < total,
        "entries": [
            {
                "id": e.id,
                "payment_id": e.payment_id,
                "account_id": e.account_id,
                "entry_type": e.entry_type,
                "event_type": e.event_type,
                "amount": float(e.amount),
                "currency": e.currency,
                "balance_after": float(e.balance_after),
                "description": e.description,
                "created_at": e.created_at.isoformat(),
            }
            for e in entries
        ],
    }


